use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    if let Value::String(s) = input {
        if let Ok(amount) = parse_amount(s) {
            return Value::Number(amount);
        }
    }
    Value::Null
}

fn parse_amount(s: String) -> Result<i64, ()> {
    let mut chars = s.chars().peekable();
    let negative = chars.peek() == Some(&'-');
    if negative {
        chars.next(); // consume the '-'
    }

    let mut whole_part = 0;
    let mut decimal_part = 0;
    let mut decimal = false;

    for c in chars {
        if c == '.' {
            if decimal {
                return Err(());
            }
            decimal = true;
        } else if c.is_digit(10) {
            if decimal {
                decimal_part = decimal_part * 10 + c.to_digit(10).unwrap() as i64;
            } else {
                whole_part = whole_part * 10 + c.to_digit(10).unwrap() as i64;
            }
        } else {
            return Err(());
        }
    }

    if decimal && decimal_part != 0 {
        if whole_part > 1000000 || whole_part == 1000000 && decimal_part > 0 {
            return Err(());
        }
        Ok(if negative {
            -(whole_part * 100 + decimal_part)
        } else {
            whole_part * 100 + decimal_part
        })
    } else if whole_part > 1000000 {
        Err(())
    } else {
        Ok(if negative {
            -whole_part * 100
        } else {
            whole_part * 100
        })
    }
}
